/** CJK 统一汉字 → GBK（大字体形码）。由 GBK 解码表生成，不是字体文件。 */
const B64 = "";
let table: Uint16Array | null = null;
const load = (): Uint16Array => {
  if (table) return table;
  const bin = Uint8Array.from(atob(B64), c => c.charCodeAt(0));
  table = new Uint16Array(bin.buffer, bin.byteOffset, bin.byteLength / 2);
  return table;
};
export const unicodeToGbk = (codePoint: number): number | null => {
  if (codePoint < 0x4E00 || codePoint > 0x9FFF) return null;
  const value = load()[codePoint - 0x4E00];
  return value || null;
};
